export class Controls{constructor(canvas,handlers){this.canvas=canvas;this.h=handlers;this.keys=new Set();this.pointer=null;window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['arrowleft','arrowright',' ','arrowup','arrowdown'].includes(k))e.preventDefault();this.keys.add(k);if(k==='escape')this.h.menu();if(k==='h')this.h.horn();if(k==='arrowleft'||k==='a')this.h.lane(-1);if(k==='arrowright'||k==='d')this.h.lane(1);if(k===' '||k==='arrowdown')this.h.brake(true);if(k==='arrowup'||k==='w')this.h.gas(true)});window.addEventListener('keyup',e=>{const k=e.key.toLowerCase();this.keys.delete(k);if(k===' '||k==='arrowdown')this.h.brake(false);if(k==='arrowup'||k==='w')this.h.gas(false)});canvas.addEventListener('pointerdown',e=>{if(e.target.closest('button,select,a,.screen,.event-card'))return;this.pointer={x:e.clientX,y:e.clientY,id:e.pointerId};try{canvas.setPointerCapture(e.pointerId)}catch{}});canvas.addEventListener('pointerup',e=>{if(!this.pointer)return;const dx=e.clientX-this.pointer.x,dy=e.clientY-this.pointer.y;if(Math.abs(dx)>28&&Math.abs(dx)>Math.abs(dy))this.h.lane(dx<0?-1:1);else if(dy<-30)this.h.gas(true);this.pointer=null});document.querySelectorAll('[data-action]').forEach(b=>{const action=b.dataset.action;const down=e=>{e.preventDefault();if(action==='left')this.h.lane(-1);else if(action==='right')this.h.lane(1);else if(action==='gas')this.h.gas(true);else if(action==='brake')this.h.brake(true);else if(action==='horn')this.h.horn()};const up=e=>{e.preventDefault();if(action==='gas')this.h.gas(false);if(action==='brake')this.h.brake(false)};b.addEventListener('pointerdown',down);b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up);b.addEventListener('pointerleave',up)})}}
